// Copies the content types generated by the Acolad backoffice, which hosts this site's content,
// into src/content/payload-types.ts.
//
//   node scripts/sync-cms-types.ts                   backoffice next to this repository
//   BACKOFFICE_DIR=/path node scripts/sync-cms-types.ts
//
// Run it after the backoffice changes the site's collections (it runs `pnpm generate:types`
// first). The copy is committed so the site builds without the backoffice sources.

import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const backoffice = path.resolve(root, process.env.BACKOFFICE_DIR ?? '../acolad-backoffice');
const source = path.join(backoffice, 'src/payload-types.ts');
const target = path.join(root, 'src/content/payload-types.ts');

const types = (await readFile(source, 'utf8'))
  // Augments the `payload` package, which this site does not install
  .replace(/\ndeclare module 'payload' \{[\s\S]*?\}\s*$/, '\n');

await writeFile(target, types);
console.log(`Types copied from ${source}`);
